 12→
 13→type openCodeAgent struct {
 14→	model   string
 15→	timeout time.Duration
 16→}
 17→
 18→func init() {
 19→	if env := os.Getenv("E2E_AGENT"); env != "" && env != "opencode" {
 20→		return
 21→	}
 22→	if _, err := exec.LookPath("opencode"); err != nil {
 23→		return
 24→	}
 25→	model := os.Getenv("E2E_OPENCODE_MODEL")
 26→	if model == "" {
 27→		model = "anthropic/claude-haiku-4-5"
 28→	}
 29→	Register(&openCodeAgent{model: model, timeout: 2 * time.Minute})
 30→}
 31→
 32→func (a *openCodeAgent) Name() string               { return "opencode" }
 33→func (a *openCodeAgent) Binary() string             { return "opencode" }
 34→func (a *openCodeAgent) EntireAgent() string        { return "opencode" }
 35→func (a *openCodeAgent) PromptPattern() string      { return `(Ask anything|▣)` }
 36→func (a *openCodeAgent) TimeoutMultiplier() float64 { return 2.0 }
 37→
 38→func (a *openCodeAgent) IsTransientError(out Output, _ error) bool {
 39→	transientPatterns := []string{
 40→		"overloaded",
 41→		"rate limit",
 42→		"529",
 43→		"503",
 44→		"ECONNRESET",
 45→		"ETIMEDOUT",
 46→		"Token refresh failed",
 47→		"database is locked",
 48→	}
 49→	for _, p := range transientPatterns {
 50→		if strings.Contains(out.Stderr, p) {
 51→			return true
 52→		}
 53→	}
 54→	return false
 55→}
 56→
 57→func (a *openCodeAgent) Bootstrap() error {
 58→	// opencode has first-run DB migration + node_modules resolution that
 59→	// races with parallel test execution (upstream issue #6935).
 60→	// Run a trivial prompt to force full initialization before tests.
 61→	for i := range 3 {
 62→		ctx, cancel := context.WithTimeout(context.Background(), 30*time.Second)
 63→		cmd := exec.CommandContext(ctx, a.Binary(), "run", "--model", a.model, "say hi")
 64→		cmd.Env = os.Environ()
 65→		out, err := cmd.CombinedOutput()
 66→		cancel()
 67→		if err == nil {
 68→			return nil
 69→		}
 70→		if i < 2 {
 71→			fmt.Fprintf(os.Stderr, "opencode warmup attempt %d failed: %s\n%s\n", i+1, err, out)
 72→			time.Sleep(5 * time.Second)
 73→		}
 74→	}
 75→	// Non-fatal: warmup failure shouldn't block tests entirely.
 76→	fmt.Fprintln(os.Stderr, "opencode warmup failed after 3 attempts, proceeding anyway")
 77→	return nil
 78→}
 79→
 80→func (a *openCodeAgent) RunPrompt(ctx context.Context, dir string, prompt string, opts ...Option) (Output, error) {
 81→	cfg := &runConfig{}
 82→	for _, o := range opts {
 83→		o(cfg)
 84→	}
 85→
 86→	model := a.model
 87→	if cfg.Model != "" {
 88→		model = cfg.Model
 89→	}
 90→
 91→	args := []string{"run"}
 92→	if model != "" {
 93→		args = append(args, "--model", model)
 94→	}
 95→	args = append(args, prompt)
 96→
 97→	timeout := a.timeout
 98→	if envTimeout := os.Getenv("E2E_TIMEOUT"); envTimeout != "" {
 99→		if parsed, err := time.ParseDuration(envTimeout); err == nil {
100→			timeout = parsed
101→		}
102→	}
103→
104→	ctx, cancel := context.WithTimeout(ctx, timeout)
105→	defer cancel()
106→
107→	cmd := exec.CommandContext(ctx, a.Binary(), args...)
108→	cmd.Dir = dir
109→	cmd.Env = filterEnv(os.Environ(), "ENTIRE_TEST_TTY")
110→
111→	var stdout, stderr strings.Builder
112→	cmd.Stdout = &stdout
113→	cmd.Stderr = &stderr
114→
115→	err := cmd.Run()
116→	out := Output{
117→		Command: a.Binary() + " " + strings.Join(args, " "),
118→		Stdout:  stdout.String(),
119→		Stderr:  stderr.String(),
120→	}
121→
122→	if err != nil {
123→		var exitErr *exec.ExitError
124→		if errors.As(err, &exitErr) {
125→			out.ExitCode = exitErr.ExitCode()
126→		} else {
127→			out.ExitCode = -1
128→		}
129→		return out, err
130→	}
131→
132→	return out, nil
133→}
134→
135→func (a *openCodeAgent) StartSession(ctx context.Context, dir string) (Session, error) {
136→	// opencode's TUI occasionally fails to render on CI (empty pane).
137→	// Retry once if the first attempt produces no output at all.
138→	var s *TmuxSession
139→	var lastErr error
140→	for attempt := range 2 {
141→		name := fmt.Sprintf("opencode-test-%d", time.Now().UnixNano())
142→		var err error
143→		s, err = NewTmuxSession(name, dir, []string{"ENTIRE_TEST_TTY"}, a.Binary(), "--model", a.model)
144→		if err != nil {
145→			return nil, err
146→		}
147→
148→		// Wait for TUI to be ready (input area with placeholder text).
149→		if _, err := s.WaitFor(`Ask anything`, 15*time.Second); err != nil {
150→			content := s.Capture()
151→			_ = s.Close()
152→			if strings.TrimSpace(content) == "" && attempt == 0 {
153→				lastErr = err
154→				continue
155→			}
156→			return nil, fmt.Errorf("waiting for startup: %w", err)
157→		}
158→		s.stableAtSend = ""
159→		return s, nil
160→	}
161→	return nil, fmt.Errorf("opencode TUI failed to start after retry: %w", lastErr)
162→}
